 void DrawTheme(object sender,DrawItemEventArgs e){if(e.Index<0)return;var t=(Theme)themes.Items[e.Index];bool selected=(e.State&DrawItemState.Selected)!=0;var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var b=new SolidBrush(Skin.Card))g.FillRectangle(b,e.Bounds);var rect=new Rectangle(e.Bounds.X+2,e.Bounds.Y+3,e.Bounds.Width-4,e.Bounds.Height-6);if(selected){using(var p=Skin.Round(rect,6))using(var b=new SolidBrush(Skin.Selected))g.FillPath(b,p);using(var p=Skin.Round(new Rectangle(rect.X+1,rect.Y+23,3,25),1.5f))using(var b=new SolidBrush(Skin.Accent))g.FillPath(b,p);}Bitmap thumbnail=ThemeThumbnail(t);if(thumbnail!=null)g.DrawImageUnscaled(thumbnail,rect.X+10,rect.Y+12);var text=new Rectangle(rect.X+66,rect.Y+13,Math.Max(1,rect.Width-74),25);TextRenderer.DrawText(g,t.Name,Font,text,Skin.Ink,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter);text.Y+=25;using(var small=new Font(Font.FontFamily,8.25f))TextRenderer.DrawText(g,(settings.ActiveId==t.Id?"使用中 · ":"")+t.Pixels+" px",small,text,Skin.Muted,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter);}
 Bitmap ThemeThumbnail(Theme t){Bitmap thumbnail;if(thumbnails.TryGetValue(t.Id,out thumbnail))return thumbnail;if(thumbnails.Count>=64)return null;thumbnail=new Bitmap(48,48);IntPtr h=Native.LoadImageW(IntPtr.Zero,Native.Paths(t)["Arrow"],2,48,48,16);if(h!=IntPtr.Zero){try{using(var draw=Graphics.FromImage(thumbnail)){IntPtr dc=draw.GetHdc();try{Native.DrawIconEx(dc,0,0,h,48,48,0,IntPtr.Zero,3);}finally{draw.ReleaseHdc(dc);}}}finally{Native.DestroyCursor(h);}}thumbnails[t.Id]=thumbnail;return thumbnail;}
 void PrepareThumbnails(){int first=Math.Max(0,themes.TopIndex),count=Math.Max(1,themes.ClientSize.Height/Math.Max(1,themes.ItemHeight)+2);for(int i=first;i<Math.Min(themes.Items.Count,first+count);i++)ThemeThumbnail((Theme)themes.Items[i]);}
 void RefreshThemes(string id){if(themes==null)return;bool before=loading;loading=true;themes.Items.Clear();foreach(var t in settings.Themes)themes.Items.Add(t);themes.SelectedItem=settings.Themes.FirstOrDefault(t=>t.Id==id);loading=before;}
 void ShowChosen(){if(!uiReady&&!building)return;bool before=loading;loading=true;themeTitle.Text=chosen==null?"当前系统指针":chosen.Name;slider.Enabled=chosen!=null;int p=chosen==null?Native.Snap(Native.DesktopSize()):Native.Snap(chosen.Pixels);slider.Value=1+(p-32)/16;sizeLabel.Text=chosen==null?"选择一套主题后可调整大小":SizeText(p);loading=before;Preview();}
 string SizeText(int p){return "指针大小     "+p+" px     ·     第 "+(1+(p-32)/16)+" / 15 档";}
 void Preview(){if(preview==null)return;string role=Native.Roles[Math.Max(0,roles.SelectedIndex)];preview.Set(chosen==null?Native.CurrentPaths()[role]:Native.Paths(chosen)[role],chosen==null?Native.DesktopSize():16+slider.Value*16);UpdatePreviewActivity();}
 void ApplyChosen(){if(chosen==null)return;var before=Backup.Capture(false);string previous=settings.ActiveId;try{Native.Apply(chosen);settings.ActiveId=chosen.Id;Store.Save(settings);}catch{settings.ActiveId=previous;try{Backup.Restore(before);}catch(Exception e){Store.Log(e);}throw;}if(uiReady)Skin.RefreshCursor(this);Evaluate(true);if(themes!=null)themes.Invalidate();}
 void ApplySize(){if(chosen==null||slider==null)return;int old=chosen.Pixels;try{chosen.Pixels=16+slider.Value*16;ApplyChosen();Preview();}catch{chosen.Pixels=old;ShowChosen();throw;}}
 void FlushSize(){if(pending){pending=false;sizeTimer.Stop();ApplySize();}}
 void RestoreOriginal(){pending=false;sizeTimer.Stop();settings.RulesEnabled=false;if(enabled!=null){loading=true;enabled.Checked=false;loading=false;}engine.Restore();Backup.Original();settings.ActiveId="";Store.Save(settings);chosen=null;RefreshThemes("");ShowChosen();tray.Visible=!Visible;UpdateState();if(state!=null)state.Text="已恢复首次使用管理器前的指针与大小";}
 void Import(ImportSession session){var groups=session.Groups();if(groups.Count==0)throw new Exception("没有找到 CUR 或 ANI 文件；安装脚本和 EXE 不会被执行。");string dir=groups[0];if(groups.Count>1)using(var pick=new ChoiceDialog(groups,session.Root)){if(pick.ShowDialog(this)!=DialogResult.OK)return;dir=pick.Selected;}using(var dialog=new MappingDialog(dir,dir==session.Root?session.SuggestedName:new DirectoryInfo(dir).Name)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;Theme t=dialog.Result;string name=t.Name;int n=2;while(settings.Themes.Any(x=>x.Name==t.Name))t.Name=name+" ("+(n++)+")";settings.Themes.Add(t);Store.Save(settings);RefreshThemes("");themes.SelectedItem=t;}}
 void DeleteTheme(){var t=chosen;if(settings.ActiveId==t.Id){Native.Apply(new Theme{Name="Windows 默认",Pixels=Native.DesktopSize()});settings.ActiveId="";}settings.Themes.Remove(t);Store.Save(settings);string dir=Path.GetFullPath(Path.Combine(Store.Library,t.Id));if(dir.StartsWith(Path.GetFullPath(Store.Library)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&Directory.Exists(dir))Directory.Delete(dir,true);Bitmap thumbnail;if(thumbnails.TryGetValue(t.Id,out thumbnail)){thumbnail.Dispose();thumbnails.Remove(t.Id);}chosen=null;RefreshThemes("");ShowChosen();Evaluate(true);}
 Rule SelectedRule(){return rules==null||rules.SelectedRows.Count==0?null:rules.SelectedRows[0].Tag as Rule;}
 void RefreshRules(){if(rules==null)return;var selected=SelectedRule();int first=rules.FirstDisplayedScrollingRowIndex,previous=rules.CurrentCell==null?0:rules.CurrentCell.RowIndex;rules.Rows.Clear();foreach(var r in settings.Rules){int i=rules.Rows.Add(r.Enabled,r.Name,r.Pixels+" px",r.Mode=="Path"?"完整路径":"进程名",r.Target);rules.Rows[i].Tag=r;}
  if(rules.Rows.Count==0)return;var row=rules.Rows.Cast<DataGridViewRow>().FirstOrDefault(x=>selected!=null&&((Rule)x.Tag).Id==selected.Id)??rules.Rows[Math.Min(previous,rules.Rows.Count-1)];rules.CurrentCell=row.Cells[1];row.Selected=true;if(first>=0)rules.FirstDisplayedScrollingRowIndex=Math.Min(first,rules.Rows.Count-1);
 }
 void EditRule(Rule r){using(var dialog=new RuleDialog(r))if(dialog.ShowDialog(this)==DialogResult.OK)Guard(delegate{var t=dialog.Result;var duplicate=settings.Rules.FirstOrDefault(x=>x.Id!=t.Id&&x.Mode==t.Mode&&String.Equals(x.Target,t.Target,StringComparison.OrdinalIgnoreCase));if(duplicate!=null)throw new Exception("该程序已有规则，请编辑现有规则。");if(r==null)settings.Rules.Add(t);else settings.Rules[settings.Rules.IndexOf(r)]=t;Store.Save(settings);RefreshRules();Evaluate(true);});}
 void Guard(Action a){try{a();}catch(Exception e){Store.Log(e);if(state!=null)state.Text="操作失败："+e.Message;MessageBox.Show(this,e.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 string Prompt(string caption,string value){using(var f=new Form{Text=caption,ClientSize=new Size(430,150),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=Font}){f.Controls.Add(new Label{Text="为这套指针取一个名字",Location=new Point(20,16),AutoSize=true});var box=new TextBox{Text=value,Location=new Point(20,48),Width=390};var ok=new FluentButton{Text="保存",Location=new Point(310,98),Size=new Size(100,34),DialogResult=DialogResult.OK,Accent=true};var cancel=new FluentButton{Text="取消",Location=new Point(200,98),Size=new Size(100,34),DialogResult=DialogResult.Cancel};f.Controls.Add(box);f.Controls.Add(ok);f.Controls.Add(cancel);f.AcceptButton=ok;f.CancelButton=cancel;Skin.Apply(f);return f.ShowDialog(this)==DialogResult.OK?box.Text:null;}}
 public void ExitNow(){quitting=true;Guard(FlushSize);try{engine.Restore();}catch(Exception e){Store.Log(e);}tray.Visible=false;Close();}
 public void CaptureView(string file){using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(file);}}
 protected override void Dispose(bool disposing){if(disposing){EndPresentation();if(watcher!=null)watcher.Dispose();if(sizeTimer!=null)sizeTimer.Dispose();if(tray!=null)tray.Dispose();foreach(var bitmap in thumbnails.Values)bitmap.Dispose();thumbnails.Clear();}base.Dispose(disposing);}
}
}
